-- Check if batsman_scored rows match ball_by_ball rows (same key)
SELECT COUNT(*) FROM batsman_scored b
JOIN ball_by_ball bb ON b.match_id = bb.match_id AND b.over_id = bb.over_id AND b.ball_id = bb.ball_id AND b.innings_no = bb.innings_no;

-- Check players in player_match but not in batting (striker)
SELECT COUNT(*) FROM player_match pm
WHERE NOT EXISTS (SELECT 1 FROM ball_by_ball bb WHERE bb.striker = pm.player_id);
